L.STRINGS = {
	["120 Merchant's Favor"] = "120 de Favor del Mercader",
	["1200 Merchant's Favor"] = "1200 de Favor del Mercader",
	["1500 Merchant's Favor"] = "1500 de Favor del Mercader",
	["180 Merchant's Favor"] = "180 de Favor del Mercader",
	["200 Merchant's Favor"] = "200 de Favor del Mercader",
	["240 Merchant's Favor"] = "240 de Favor del Mercader",
	["270 Merchant's Favor"] = "270 de Favor del Mercader",
	["360 Merchant's Favor"] = "360 de Favor del Mercader",
	["60 Merchant's Favor"] = "60 de Favor del Mercader",
	["6000 Merchant's Favor"] = "6000 de Favor del Mercader",
	["90 Merchant's Favor"] = "90 de Favor del Mercader",
	["A 1.5-second cast: a 3-minute curse that hurts the player now and then when they attack. Remove it."] = "Lanzamiento de 1.5 s: una maldición de 3 min que daña al jugador de vez en cuando al atacar. Quítenla.",
	["A 2-second cast, then for 6 seconds arcane energy hits everyone within 25 yards every 2 seconds, for about 140 damage each time. Ranged players, stay beyond 25 yards; melee, step out during the cast."] = "Lanzamiento de 2 s; luego, durante 6 s, la energía arcana golpea cada 2 s a todos los que estén a menos de 25 m, con unos 140 de daño cada vez. Jugadores a distancia, quédense a más de 25 m; cuerpo a cuerpo, aléjense durante el lanzamiento.",
	["A 2-second cast: a hit, then Nature damage for a minute. Cure the poison."] = "Lanzamiento de 2 segundos: un golpe y luego daño de Naturaleza durante un minuto. Cura el veneno.",
	["A 2-second cast: arcane power drains up to 200 mana from everyone within 45 yards of him."] = "Lanzamiento de 2 s: el poder arcano drena hasta 200 de maná a todos los que estén a menos de 45 m de él.",
	["A 3-second Shadow bolt on the tank, over and over. Interrupt it."] = "Una descarga de Sombras de 3 s sobre el tanque, una y otra vez. Interrúmpela.",
	["A Better Ingredient"] = "Un ingrediente mejor",
	["A Binding Contract"] = "Un contrato vinculante",
	["A Blackrock orc who can be found in one of four cells."] = "Un orco Roca Negra que puede estar en una de cuatro celdas.",
	["A Broken Trap"] = "Una trampa rota",
	["A Crumpled Up Note"] = "Una nota arrugada",
	["A Crumpled Up Note, dropped by foes inside the dungeon"] = "Una nota arrugada, botín de enemigos dentro del calabozo",
	["A Curious Pair"] = "Una curiosa pareja",
	["A Dark Iron dwarf held for his part in the Thandol Span attacks."] = "Un enano Hierro Negro encerrado por su papel en los ataques al Puente Thandol.",
	["A Dull and Flat Elven Blade"] = "Una hoja élfica desafilada",
	["A dust storm hits the whole group now and then, and he slows the tank."] = "De vez en cuando, una tormenta de polvo golpea a todo el grupo, y además ralentiza al tanque.",
	["A Dynamite Plan"] = "Un plan con dinamita",
	["A fallen paladin who heals himself and shields himself from harm."] = "Un paladín caído que se sana a sí mismo y se protege con escudos.",
	["A Fanglord who turns into a serpent partway through the fight."] = "Un señor del Colmillo que se convierte en serpiente a mitad del combate.",
	["A felguard standing in the middle of the lava lake, and the hardest-hitting boss here."] = "Un guardia vil plantado en medio del lago de lava, y el jefe que más fuerte pega aquí.",
	["A Fine Mess"] = "Un buen lío",
	["A Frightened Request"] = "Una petición temerosa",
	["A giant turtle in the first great pool."] = "Una tortuga gigante en el primer gran estanque.",
	["A giant turtle that will not attack first; killing him is optional."] = "Una tortuga gigante que no ataca primero; matarla es opcional.",
	["A Green Sample"] = "Una muestra verde",
	["A Grim Fate"] = "Un destino funesto",
	["A heavy blow that knocks the tank back."] = "Un golpe fuerte que empuja al tanque hacia atrás.",
	["A heavy swing at everyone in front of him. Only the tank should stand there."] = "Un golpe pesado contra todos los que tiene delante. Solo el tanque debería colocarse ahí.",
	["A hidden elite you summon yourself."] = "Un élite oculto que invocas tú mismo.",
	["A Host of Evil"] = "Un anfitrión del mal",
	["A huge violet raptor, the leader of Stalker's Thicket."] = "Un enorme raptor violeta, el líder del Matorral del Acechador.",
	["A large health pool"] = "Mucha salud",
	["A lightning bolt that jumps to a second player. Interrupt it."] = "Un relámpago que salta a un segundo jugador. Interrúmpelo.",
	["A mage or a druid can remove his Call of the Grave before it goes off. He fears, and drains two players below half health."] = "Un mago o un druida puede quitar su Llamada de la tumba antes de que se active. Provoca miedo y, por debajo de la mitad de su salud, drena a dos jugadores.",
	["A mage quest. The Obsidian Sentinel inside Uldaman carries the power source."] = "Misión de mago. El Centinela obsidiana que hay dentro de Uldaman lleva la fuente de poder.",
	["A mage trainer in a capital"] = "Un instructor de magos en una capital",
	["A magic debuff on the tank: around 65 Arcane damage every 2 seconds for 10 seconds. Dispel it."] = "Un perjuicio mágico sobre el tanque: unos 65 de daño Arcano cada 2 s durante 10 s. Disípenlo.",
	["A magic dispel removes his Shadow Word: Pain."] = "Una disipación de Magia elimina su Palabra de las Sombras: dolor.",
	["A massive plant creature; optional."] = "Una enorme criatura vegetal; opcional.",
	["A Moon-Kissed Blade"] = "Una hoja besada por la luna",
	["A murloc chieftain in his shrine. His followers run for help when they are low on health, so finish them off."] = "Un cabecilla múrloc en su santuario. Sus seguidores huyen a pedir ayuda cuando les queda poca salud, así que remátalos.",
	["A naga sorceress in a side cavern off the pool; optional."] = "Una hechicera naga en una caverna lateral del estanque; opcional.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Jordan's Smithing Hammer, picked up from Jordan's Hammer in the courtyard. The rest: Whitestone Oak Lumber in the Deadmines, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Misión de paladín para humanos y enanos, con partes en varios lugares. Aquí: el Martillo de herrería de Jordan, que se recoge del Martillo de Jordan en el patio. El resto: la Madera de roble de Piedrablanca en las Minas de la Muerte, la Gema kor en las Cavernas de Brazanegra y el Envío de mena de Jordan en Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: the Corrupted Kor Gem, from the Blackfathom Sea Witches inside or the Tide Priestesses and Oracles at the entrance in Ashenvale; Thundris Windweaver in Auberdine cleanses it. The rest: Whitestone Oak Lumber in the Deadmines, Jordan's Smithing Hammer in Shadowfang Keep and Jordan's ore shipment in Loch Modan."] = "Una misión de paladín para humanos y enanos, con partes en varios lugares. Aquí: la Gema kor corrupta, de las Brujas de mar Brazanegra del interior o de las Sacerdotisas de las mareas y los Oráculos de la entrada, en Vallefresno; Thundris Tejevientos, en Auberdine, la purifica. El resto: la Madera de roble de Piedrablanca en las Minas de la Muerte, el Martillo de herrería de Jordan en el Castillo de Colmillo Oscuro y el envío de mena de Jordan en Loch Modan.",
	["A paladin quest for humans and dwarves, with parts from several places. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop. The rest: Jordan's Smithing Hammer in Shadowfang Keep, the Kor Gem in Blackfathom Deeps and Jordan's ore shipment in Loch Modan."] = "Misión de paladín para humanos y enanos, con partes en varios lugares. Aquí: la Madera de roble de Piedrablanca, que sueltan los Talladores de madera goblin. El resto: el Martillo de herrería de Jordan en el Castillo de Colmillo Oscuro, la Gema kor en las Cavernas de Brazanegra y el Envío de mena de Jordan en Loch Modan.",
	["A paladin quest for the Forsaken. Here: Whitestone Oak Lumber, which the Goblin Woodcarvers drop."] = "Misión de paladín para los Renegados. Aquí: la Madera de roble de Piedrablanca, que sueltan los Talladores de madera goblin.",
	["A patrol"] = "Una patrulla",
	["A Pawn on the Eternal Board"] = "Un peón en el ajedrez de la vida",
	["A pillar of flame where a player stands (3-second cast): Fire damage, then more every 3 seconds for 9 seconds. Step out of it."] = "Una columna de llamas donde se encuentra un jugador (lanzamiento de 3 s): daño de Fuego y luego más cada 3 s durante 9 s. Sal de ella.",
	["A player takes more Physical damage for 10 minutes (2-second cast). A mage or a druid can remove it."] = "Un jugador recibe más daño físico durante 10 min (lanzamiento de 2 s). Un mago o un druida puede quitarla.",
	["A Portable Power Source"] = "Fuente de energía portátil",
	["A priest or a shaman can remove his Bloodlust."] = "Un sacerdote o un chamán puede quitarle Ansia de sangre.",
	["A quilboar geomancer close to the Kraul's entrance."] = "Un geomántico jabaespín cerca de la entrada del Horado.",
	["A raid new in WoW: Forever, on Mount Hyjal. Its bosses and loot are not known yet."] = "Una banda nueva de WoW: Forever, en el Monte Hyjal. Aún no se conocen sus jefes ni su botín.",
	["A raid new in WoW: Forever. Its bosses and loot are not known yet."] = "Una banda nueva de WoW: Forever. Aún no se conocen sus jefes ni su botín.",
	["A rare bat in a small recess of the bat cave near Charlga Razorflank: not every run meets it."] = "Un murciélago raro en un pequeño hueco de la cueva de los murciélagos, cerca de Charlga Filonavaja: no aparece en todas las partidas.",
	["A rare bat, not there on every run. When it is, it waits in a small recess in the wall of the bat cave near Charlga Razorflank."] = "Un murciélago raro que no aparece en todas las partidas. Cuando aparece, espera en un pequeño hueco en la pared de la cueva de los murciélagos, cerca de Charlga Filonavaja.",
	["A rare spawn: not every run meets him."] = "Una criatura rara: no aparece en todas las visitas al calabozo.",
	["A rare spawn: not every run meets him. At 15% health he runs for help."] = "Una criatura rara: no aparece en todas las partidas. Al 15% de salud, huye a pedir ayuda.",
	["A rare. A Stone Rumbler fights with him; interrupt his Lightning Bolt, and finish him before he runs for help at 15% health."] = "Un enemigo raro. Un Estruendor de piedra lucha con él; interrumpe su Descarga de relámpagos y acaba con él antes de que huya en busca de ayuda al 15% de salud.",
	["A rare. He calls two Burning Servants; interrupt his Fireball, and a priest or a shaman can remove his fire shield."] = "Un enemigo raro. Llama a dos Sirvientes ardientes; interrumpe su Bola de Fuego. Un sacerdote o un chamán puede quitarle su escudo de fuego.",
	["A rare. He cuts the tank's armour by three quarters, and at 15% health runs for help: finish him first."] = "Criatura rara. Reduce la armadura del tanque en tres cuartas partes y, al 15% de salud, huye a pedir ayuda: acaba con él antes.",
	["A Reliquary of Purity"] = "Un relicario de Pureza",
	["A satyr on the walkway above Jergosh's chamber."] = "Un sátiro en la pasarela sobre la cámara de Jergosh.",
	["A Searing Blade warlock; clear the cultists around him first."] = "Un brujo de la Hoja Abrasadora; elimina primero a los cultores que lo rodean.",
	["A Shifty Merchant"] = "Un mercader sospechoso",
	["A Shred of Hope"] = "Una brizna de esperanza",
	["A Sign of Hope"] = "Un signo de esperanza",
	["A slow heal (3.5 seconds) on himself or an ally. Interrupt it."] = "Una sanación lenta (3.5 s) sobre sí mismo o un aliado. Interrúmpela.",
	["A step of the warlock's Dreadsteed quests."] = "Un paso de las misiones del corcel nefasto del brujo.",
	["A Stone Rumbler fights at his side; interrupt his Lightning Bolt."] = "Un Estruendor de piedra lucha a su lado; interrumpe su Descarga de relámpagos.",
	["A Stone Rumbler stands with him and fights at his side."] = "Un Estruendor de piedra lo acompaña y lucha a su lado.",
	["A storm of dust that hits the group for about 160 to 330 nature damage. Healers, be ready for it."] = "Una tormenta de polvo que inflige al grupo entre 160 y 330 de daño de Naturaleza, aproximadamente. Sanadores, estén preparados.",
	["A Taste of Flame"] = "Un sabor a llamarada",
	["A test of the tank: he hits hard, disarms, and his Unholy Frenzy speeds his attacks by 75% for 20 seconds. Purge or dispel the frenzy, and tanks should bring a shield."] = "Una prueba para el tanque: golpea fuerte, desarma y su Frenesí profano acelera sus ataques un 75% durante 20 s. Purguen o disipen el frenesí; los tanques deberían llevar escudo.",
	["A threshadon in the underwater cave; optional. He only melees."] = "Un trillanodonte en la cueva submarina; opcional. Solo ataca cuerpo a cuerpo.",
	["A thunder lizard in the water; killing him is optional."] = "Un truenagarto en el agua; matarlo es opcional.",
	["A Titan dig site above Whelgar's Excavation, caught out of time, where the Titans' constructs answer to no one now. Inside: the Lost Marsh, Stalker's Thicket, the Site of the Guardian and the Lost Dig Site."] = "Una excavación de los titanes sobre la Excavación de Whelgar, atrapada fuera del tiempo, donde los constructos de los titanes ya no obedecen a nadie. Dentro: el Marjal Perdido, el Matorral del Acechador, el Sitio del Guardián y la Excavación Perdida.",
	["A titan site hidden in Un'Goro Crater, guarding secrets of the makers among the crater's dinosaurs."] = "Un enclave titánico oculto en el Cráter de Un'Goro que guarda secretos de los Creadores entre los dinosaurios del cráter.",
	["A Titan vault buried under the Badlands, where Dark Iron dwarves and troggs dig for the secrets of the earthen, and the stone keeper Archaedas guards the deepest hall."] = "Una cámara de los titanes enterrada bajo las Tierras Inhóspitas, donde los enanos Hierro Negro y los troggs excavan en busca de los secretos de los terráneos, y el guardián de piedra Archaedas custodia la sala más profunda.",
	["A treant twisted by fel magic, among the Suffused Treants in the streets."] = "Un antárbol corrompido por la magia vil, entre los Antárboles infundidos de las calles.",
	["A trogg brute on the main path; a straightforward fight if no other packs join in."] = "Un trogg bruto en el camino principal; un combate sencillo si no se suman otros grupos de enemigos.",
	["A troll city that sank into the ocean long ago has risen again, and naga, pirates and stranger things from the deep have claimed its streets."] = "Una ciudad trol que se hundió en el océano hace mucho tiempo ha vuelto a emerger, y nagas, piratas y cosas aún más extrañas de las profundidades se han adueñado de sus calles.",
	["A Twilight's Hammer shaman patrolling the tunnels."] = "Un chamán del Martillo Crepuscular que patrulla los túneles.",
	["A vast cavern under Desolace, sacred to the centaur, where Princess Theradras, daughter of Therazane, has fouled the waters and the resting place of Zaetar."] = "Una vasta caverna bajo Desolace, sagrada para los centauros, donde la princesa Theradras, hija de Therazane, corrompió las aguas y el lugar de descanso de Zaetar.",
	["A Vengeful Fate"] = "Un destino vengador",
	["A Visit to Gregan"] = "Visita a Gregan",
	["A ward closes his cave. Kill the two Death's Head Ward Keepers standing in front of it: the ward goes down when both are dead."] = "Una barrera cierra su cueva. Mata a los dos Guardas Caramuerte que están frente a ella: la barrera cae cuando ambos mueren.",
	["A ward seals his cave: kill the two Death's Head Ward Keepers in front of it to bring it down."] = "Una barrera sella su cueva: mata a los dos Guardas Caramuerte que están frente a ella para derribarla.",
	["A warlock quest. The 3 Soran'ruk Fragments drop from Twilight Acolytes here; the Large Soran'ruk Fragment comes from Shadowfang Darksouls in Shadowfang Keep."] = "Una misión de brujo. Los 3 Trozos Soran'ruk los sueltan aquí los Acólitos Crepusculares; el Trozo de Soran'ruk grande lo sueltan los Almanegras Colmillo Oscuro en el Castillo de Colmillo Oscuro.",
	["A warlock quest. The fragments come from here and from Blackfathom Deeps."] = "Misión de brujo. Los trozos se consiguen aquí y en las Cavernas de Brazanegra.",
	["A way to remove a curse or cure a disease comes in handy. Otherwise an easy fight: clear the room before the pull."] = "Viene bien poder eliminar maldiciones o curar enfermedades. Por lo demás, un combate fácil: limpia la sala antes de atraerlo.",
	["A white crocolisk of the marsh."] = "Un crocolisco blanco del marjal.",
	["A White Punch Card drops from mobs outside the instance; run it through Matrix Punchograph 3005-A (Train Depot, outside), 3005-B (the Dormitory), 3005-C (Electrocutioner 6000's platform) and 3005-D (lower Engineering Labs) to get the Prismatic Punch Card."] = "Los enemigos de fuera de la instancia sueltan una Tarjeta perforada blanca; pásala por el Perforágrafo Matriz 3005-A (Depósito de Trenes, afuera), el 3005-B (los Dormitorios), el 3005-C (la plataforma del Electrocutor 6000) y el 3005-D (parte baja de los Laboratorios de Ingeniería) para obtener la Tarjeta perforada centelleante.",
	["Abandoned Hope"] = "Esperanza perdida",
	["Abominable Creatures"] = "Criaturas abominables",
	["Abominable Head"] = "Cabeza abominable",
	["About every 20 seconds he fears up to three players near him: a shaman's Tremor Totem helps. Late in the fight he enrages."] = "Cada 20 s, más o menos, aterroriza hasta a tres jugadores cercanos: el Tótem de tremor de un chamán ayuda. Al final del combate se enfurece.",
	["About every 20 seconds he roars and fears up to three players near him. A shaman's Tremor Totem helps."] = "Cada 20 s, más o menos, ruge y aterroriza hasta a tres jugadores cercanos. El Tótem de tremor de un chamán ayuda.",
	["About one run in three, one of the graveyard's three rares stands at one of six places: Azshir the Sleepless, the Fallen Champion or Ironspine."] = "Más o menos en una de cada tres partidas, uno de los tres enemigos raros del cementerio aparece en uno de seis puntos: Azshir el Insomne, el Campeón caído o Dorsacerado.",
	["About one run in three, one of the graveyard's three rares stands at one of the six places on the map: Azshir the Sleepless, Fallen Champion or Ironspine."] = "Más o menos en una de cada tres partidas, uno de los tres enemigos raros del cementerio aparece en uno de los seis puntos del mapa: Azshir el Insomne, Campeón caído o Dorsacerado.",
	["Above and Beyond"] = "Por encima y más allá",
	["Accept Rig Wars from Nogg first; you need not finish it. If Nogg no longer offers Rig Wars, abandon this quest and Rig Wars comes back. Leads to Gnomer-gooooone!, the goblins' transporter to Gnomeregan."] = "Primero pídele a Nogg la misión Las guerras de la plataforma; no hace falta completarla. Si Nogg ya no la ofrece, abandona esta misión y volverá a aparecer. Continúa con ¡Gnomer-yaaaaa!, el transportador de los goblins a Gnomeregan.",
	["Acid Splash hurts everyone near him over time. Interrupt his heal below half health; at 15% he runs for help."] = "Salpicadura ácida daña con el tiempo a todos los que estén cerca de él. Interrumpe su sanación por debajo de la mitad de su salud; al 15% huye a pedir ayuda.",
	["Advisor Belgrum"] = "Consejero Belgrum",
	["Advisor Belgrum, Hall of Explorers, Ironforge"] = "Consejero Belgrum, Sala de los Expedicionarios, Forjaz",
	["Afadra Dunwall, Ironforge"] = "Afadra Dunwall, Forjaz",
	["After 60 seconds, Shadow damage to the player (2-second cast). A mage or a druid can remove it before then."] = "Tras 60 s, daño de Sombras al jugador (lanzamiento de 2 s). Un mago o un druida puede quitarla antes.",
	["After a 3-second cast, a beam comes out in front of it for 6 seconds and hits four times a second. Get out of its path as soon as the cast starts."] = "Tras un lanzamiento de 3 s, sale un rayo frente a ella durante 6 s que golpea cuatro veces por segundo. Salgan de su trayectoria en cuanto empiece el lanzamiento.",
	["After the fight, open the room's vaults: about 24 Dwarven Heirlooms for Important Heirlooms, and the stone tablet that starts The Treaty of Understanding."] = "Después del combate, abre las bóvedas de la sala: unas 24 Reliquias enanas para Reliquias importantes, y la tablilla de piedra que inicia El Tratado de Entendimiento.",
	["After the fight, open the vaults of the room: about 24 Dwarven Heirlooms for Important Heirlooms, and the tablet of The Treaty of Understanding."] = "Después del combate, abre las bóvedas de la sala: unas 24 Reliquias enanas para Reliquias importantes, y la tablilla de El Tratado de Entendimiento.",
	["Agmond's Fate"] = "El sino de Agmond",
	["Aku'mai's Lair"] = "Guarida de Aku'mai",
	["Alba Fairmoon"] = "Alba Lunaclara",
	["Alba Fairmoon gives it at Sentinel Hill at the end of her chain, after a trip to Stormwind for ten Coarse Dynamite for Sprite Jumpsprocket. The forge is in the foundry, where Gilnid is fought; she then waits at the dungeon's exit with the detonator."] = "Alba Lunaclara la da en la Colina del Centinela al final de su cadena, tras un viaje a Ventormenta por diez Dinamitas burdas para Duendy Ruedadentada. La forja está en la fundición, donde se combate a Gilnid; después ella espera en la salida del calabozo con el detonador.",
	["Alba Fairmoon, at the Deadmines' exit"] = "Alba Lunaclara, en la salida de las Minas de la Muerte",
	["Alba Fairmoon, at the Deadmines' exit, Westfall"] = "Alba Lunaclara, en la salida de las Minas de la Muerte, Páramos de Poniente",
	["Alba Fairmoon, Sentinel Hill, Westfall"] = "Alba Lunaclara, Colina del Centinela, Páramos de Poniente",
	["Alcaz Island, Dustwallow Marsh"] = "Isla de Alcaz, Marjal Revolcafango",
	["Alexi Barov, Tirisfal Glades"] = "Alexi Barov, Claros de Tirisfal",
	["Allegiance to the Old Gods"] = "Lealtad a los dioses antiguos",
	["Also from Courier Hammerfall in Ironforge and Herald Moonstalker in Darnassus."] = "También la ofrecen el mensajero Sentencia en Forjaz y el heraldo Acechalunas en Darnassus.",
	["Also from Harbinger Balthazad in Undercity and Bluff Runner Windstrider in Thunder Bluff."] = "También la ofrecen el presagista Balthazad en Entrañas y el asaltaviento Correbrisa en Cima del Trueno.",
